<script setup lang="ts">
import { dateTime } from '../../utils/core-date-time'
import ConsoleDrawer from '../../console-ui/ConsoleDrawer.vue'
import ConsoleDialog from '../../console-ui/ConsoleDialog.vue'
import ConsoleDiscardChangesDialog from '../../console-ui/ConsoleDiscardChangesDialog.vue'
import ConsoleValidatedForm from '../../console-ui/ConsoleValidatedForm.vue'
import ConsoleQueryButton from '../../console-ui/ConsoleQueryButton.vue'
import ConsoleDataTable from '../../console-ui/ConsoleDataTable.vue'
import ConsoleListFilters from '../../console-ui/ConsoleListFilters.vue'
import ConsoleListSearch from '../../console-ui/ConsoleListSearch.vue'
import ConsoleInput from '../../console-ui/ConsoleInput.vue'
import ConsoleSettingsField from '../../console-ui/ConsoleSettingsField.vue'
import ConsoleFormActions from '../../console-ui/ConsoleFormActions.vue'
definePageMeta({ middleware: 'core-access', corePermission: 'core.content.read', key: route => route.path })
type Category={id:string;name:string;sort:number;enabled:boolean;version:number;updatedAt:string}
type Article={id:string;title:string;sort:number;enabled:boolean;version:number;updatedAt:string;category:Category}
type Listing={canWrite:boolean;categories:Category[];items:Article[];total:number;page:number;pageSize:number}
const {api}=useCoreApi(), {data:account}=await useCoreSession()
const toast=useToast(),endpoint='/admin/help'
const tab=useRouteTab<string>('articles',['articles','categories']),q=ref(''),category=ref('all'),status=ref('all'),page=ref(1),pageSize=ref(20),applied=ref({q:'',category:'all',status:'all'})
const params=()=>new URLSearchParams({q:applied.value.q,...(applied.value.category!=='all'?{categoryId:applied.value.category}:{}),status:applied.value.status,page:String(page.value),pageSize:String(pageSize.value)})
const initial=await useAsyncData<Listing>('help:'+account.value?.account.id,(_nuxt,{signal})=>api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal}))
const data=ref<Listing>(initial.data.value||{canWrite:false,categories:[],items:[],total:0,page:1,pageSize:20}),error=ref(initial.error.value?.message||''),loadAction=ref(''),mutation=ref('')
const lifetime=new AbortController();let controller:AbortController|undefined,sequence=0,disposed=false
const categoryOpen=ref(false),categoryId=ref(''),categoryVersion=ref(0),form=ref({name:'',sort:0,enabled:true}),baseline=ref(''),formError=ref(''),dirty=computed(()=>categoryOpen.value&&JSON.stringify(form.value)!==baseline.value),discard=useDiscardChanges(()=>!!mutation.value)
const deletion=ref<{type:string;row:Category|Article}|null>(null),deleteError=ref('')
const columns=[{accessorKey:'title',header:'文章标题'},{id:'category',header:'分类'},{accessorKey:'sort',header:'排序'},{id:'status',header:'状态'},{accessorKey:'updatedAt',header:'修改时间'},{id:'actions',header:'操作'}]
const categoryColumns=[{accessorKey:'name',header:'分类名称'},{accessorKey:'sort',header:'排序'},{id:'status',header:'状态'},{accessorKey:'updatedAt',header:'修改时间'},{id:'actions',header:'操作'}]
async function load(source='refresh'){
 if(disposed)return;controller?.abort();controller=new AbortController();const attempt=++sequence;loadAction.value=source
 try{const value=await api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,controller.signal])});if(!disposed&&attempt===sequence){data.value=value;page.value=value.page;error.value=''}}catch(e:any){if(!disposed&&attempt===sequence)error.value=e.message||'帮助内容读取失败'}finally{if(!disposed&&attempt===sequence)loadAction.value=''}
}
function filter(source:'search'|'reset'){if(mutation.value)return;if(source==='reset'){q.value='';category.value='all';status.value='all'}applied.value={q:q.value.trim(),category:category.value,status:status.value};page.value=1;void load(source)}
function changePage(value:number){if(mutation.value||value===page.value)return;page.value=value;void load('page')}
function changePageSize(value:number){if(mutation.value||value===pageSize.value)return;pageSize.value=value;page.value=1;void load('page')}
function editCategory(row?:Category){categoryId.value=row?.id||crypto.randomUUID();categoryVersion.value=row?.version||0;form.value={name:row?.name||'',sort:row?.sort||0,enabled:row?.enabled??true};baseline.value=JSON.stringify(form.value);formError.value='';categoryOpen.value=true}
function closeCategory(){if(mutation.value)return;if(dirty.value){discard.request(()=>{categoryOpen.value=false});return}categoryOpen.value=false}
async function saveCategory(){if(mutation.value||!data.value.canWrite)return;mutation.value='category-save';formError.value='';try{await api(endpoint+'/categories/'+categoryId.value,'PUT',{version:categoryVersion.value,...form.value,sort:Number(form.value.sort)},{signal:lifetime.signal});if(!disposed){categoryOpen.value=false;toast.add({title:'分类已保存',color:'success'});await load('mutation')}}catch(e:any){if(!disposed)formError.value=e.message||'保存失败'}finally{if(!disposed)mutation.value=''}}
function askDelete(type:string,row:Category|Article){deletion.value={type,row};deleteError.value=''}
async function remove(){if(mutation.value||!deletion.value)return;mutation.value='delete';deleteError.value='';try{await api(endpoint+'/'+deletion.value.type+'/'+deletion.value.row.id,'DELETE',{version:deletion.value.row.version},{signal:lifetime.signal});if(!disposed){deletion.value=null;toast.add({title:'已删除',color:'success'});await load('mutation')}}catch(e:any){if(!disposed)deleteError.value=e.message||'删除失败'}finally{if(!disposed)mutation.value=''}}
const editor=(id?:string)=>({path:'/admin/help-editor',query:id?{id}:{}})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||mutation.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload))
onBeforeRouteLeave(to=>{if(mutation.value)return false;if(dirty.value){discard.request(()=>{categoryOpen.value=false;void navigateTo(to.fullPath)});return false}})
onBeforeUnmount(()=>{disposed=true;sequence++;controller?.abort();lifetime.abort();if(import.meta.client)window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><CoreShell title="帮助中心" :refresh-page="() => load('refresh')">
 <template #actions><UButton v-if="data.canWrite" icon="i-lucide-plus" :disabled="!!mutation" :to="tab==='articles'?editor():undefined" @click="tab==='categories'&&editCategory()">{{tab==='articles'?'新建文章':'新建分类'}}</UButton></template>
 <div class="space-y-5">
 <div class="flex flex-wrap items-center justify-between gap-3"><UTabs v-model="tab" :content="false" :items="[{label:'帮助文章',value:'articles'},{label:'帮助分类',value:'categories'}]"/></div>
 <template v-if="tab==='articles'"><form class="core-editor" @submit.prevent="filter('search')"><ConsoleListFilters><ConsoleListSearch v-model="q" placeholder="搜索标题或正文" :maxlength="100" :disabled="!!mutation"/><USelect v-model="category" :items="[{label:'全部分类',value:'all'},...data.categories.map(c=>({label:c.name,value:c.id}))]" aria-label="帮助分类" :disabled="!!mutation"/><USelect v-model="status" :items="[{label:'全部状态',value:'all'},{label:'显示',value:'enabled'},{label:'隐藏',value:'disabled'}]" aria-label="文章状态" :disabled="!!mutation"/><div class="flex shrink-0 items-center gap-3"><ConsoleQueryButton type="submit" :loading="loadAction==='search'" :disabled="!!mutation">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="loadAction==='reset'" :disabled="!!mutation" @click="filter('reset')">重置</ConsoleQueryButton></div></ConsoleListFilters></form>
 <ConsoleDataTable :data="data.items" :columns="columns" :page="page" :page-size="pageSize" :page-size-items="[10,20,50]" :total="data.total" :client-pagination="false" :error="error" empty-title="暂无帮助文章" empty-description="先创建帮助分类，再添加文章。" min-table-width="850px" @retry="load('retry')" @update:page="changePage" @update:page-size="changePageSize"><template #errorActions><UButton :loading="loadAction==='retry'" @click="load('retry')">重试</UButton></template><template #category-cell="{row}">{{row.original.category.name}}</template><template #status-cell="{row}"><UBadge :color="row.original.enabled&&row.original.category.enabled?'success':'neutral'" variant="subtle">{{!row.original.enabled?'隐藏':!row.original.category.enabled?'分类已隐藏':'显示'}}</UBadge></template><template #updatedAt-cell="{row}">{{dateTime(row.original.updatedAt)}}</template><template #actions-cell="{row}"><UButton variant="link" size="sm" :to="editor(row.original.id)">{{data.canWrite?'编辑':'查看'}}</UButton><UButton v-if="data.canWrite" variant="link" color="error" size="sm" :disabled="!!mutation" @click="askDelete('articles',row.original)">删除</UButton></template></ConsoleDataTable></template>
 <ConsoleDataTable v-else :data="data.categories" :columns="categoryColumns" :pagination="false" :error="error" empty-title="暂无帮助分类" min-table-width="650px" @retry="load('retry')"><template #errorActions><UButton :loading="loadAction==='retry'" @click="load('retry')">重试</UButton></template><template #status-cell="{row}"><UBadge :color="row.original.enabled?'success':'neutral'" variant="subtle">{{row.original.enabled?'显示':'隐藏'}}</UBadge></template><template #updatedAt-cell="{row}">{{dateTime(row.original.updatedAt)}}</template><template #actions-cell="{row}"><UButton v-if="data.canWrite" variant="link" size="sm" :disabled="!!mutation" @click="editCategory(row.original)">编辑</UButton><UButton v-if="data.canWrite" variant="link" color="error" size="sm" :disabled="!!mutation" @click="askDelete('categories',row.original)">删除</UButton><span v-if="!data.canWrite">—</span></template></ConsoleDataTable>
 <ConsoleDrawer :open="categoryOpen" :title="categoryVersion?'编辑帮助分类':'新建帮助分类'" :dismissible="!mutation" @update:open="!$event&&closeCategory()"><template #body><ConsoleValidatedForm id="help-category-form" class="space-y-6" @submit="saveCategory" @invalid="formError=$event"><UAlert v-if="formError" color="error" :title="formError"/><ConsoleSettingsField label="分类名称" input-id="help-category-name"><ConsoleInput id="help-category-name" v-model="form.name" required :maxlength="80" :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="排序" input-id="help-category-sort"><ConsoleInput id="help-category-sort" v-model="form.sort" type="number" min="0" max="999999" step="1" required :disabled="!!mutation"/><p class="mt-2 text-xs text-muted">数字越大越靠前。</p></ConsoleSettingsField><ConsoleSettingsField label="客户端显示"><USwitch v-model="form.enabled" :disabled="!!mutation" aria-label="分类在客户端显示"/><p class="mt-2 text-xs text-muted">隐藏分类后，其下所有文章也将从客户端隐藏。</p></ConsoleSettingsField></ConsoleValidatedForm></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="!!mutation" @click="closeCategory">取消</UButton><UButton type="submit" form="help-category-form" :loading="mutation==='category-save'" :disabled="!!mutation||!dirty">保存</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <ConsoleDialog :open="!!deletion" title="确认删除" size="form" :dismissible="!mutation" @update:open="!$event&&!mutation&&(deletion=null)"><template #body><p>删除“{{deletion&&('title' in deletion.row?deletion.row.title:deletion.row.name)}}”后，客户端将无法查看。</p><UAlert v-if="deleteError" class="mt-4" color="error" :title="deleteError"/></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" :disabled="!!mutation" @click="deletion=null">取消</UButton><UButton color="error" :loading="mutation==='delete'" :disabled="!!mutation" @click="remove">删除</UButton></ConsoleFormActions></template></ConsoleDialog>
 <ConsoleDiscardChangesDialog :controller="discard"/>
</div></CoreShell></template>
